From dbaa5a71a72d20ab7969775341270f3a1e7be394 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:13:37 +0100
Subject: [PATCH] libtaskmanager: keep launchers of other activities in place

Moving a launcher put every launcher hidden on the current activity at
the end of the list, so launchers pinned to other activities lost their
place. Each one now stays right after the launcher it used to follow.

BUG: 484219
---
 libtaskmanager/tasksmodel.cpp | 27 ++++++++++++++++++++++++---
 1 file changed, 24 insertions(+), 3 deletions(-)

diff --git a/libtaskmanager/tasksmodel.cpp b/libtaskmanager/tasksmodel.cpp
index fd6246a363..3bfba21eea 100644
--- a/libtaskmanager/tasksmodel.cpp
+++ b/libtaskmanager/tasksmodel.cpp
@@ -1857,7 +1857,9 @@ void TasksModel::syncLaunchers()
     }

     QMap<int, QString> sortedShownLaunchers;
-    QStringList sortedHiddenLaunchers;
+    QStringList leadingHiddenLaunchers;
+    QHash<int, QStringList> hiddenLaunchersAfterRow;
+    QList<std::pair<int, QList<QStringView>>> precedingShownLaunchers;

     for (const auto launchers = launcherList(); const QString &launcherUrlStr : launchers) {
         int row = -1;
@@ -1886,8 +1888,21 @@ void TasksModel::syncLaunchers()

         if (row != -1) {
             sortedShownLaunchers.insert(row, launcherUrlStr);
+            precedingShownLaunchers.prepend({row, activities});
         } else {
-            sortedHiddenLaunchers << launcherUrlStr;
+            // Keep launchers hidden on this activity after the nearest preceding
+            // shown launcher that is also visible wherever they are.
+            const auto anchor = std::ranges::find_if(precedingShownLaunchers, [&activities](const auto &shown) {
+                return shown.second.contains(QStringView(NULL_UUID)) || std::ranges::all_of(activities, [&shown](QStringView activity) {
+                           return shown.second.contains(activity);
+                       });
+            });
+
+            if (anchor != precedingShownLaunchers.end()) {
+                hiddenLaunchersAfterRow[anchor->first] << launcherUrlStr;
+            } else {
+                leadingHiddenLaunchers << launcherUrlStr;
+            }
         }
     }

@@ -1913,7 +1928,13 @@ void TasksModel::syncLaunchers()
         }
     }

-    setLauncherList(sortedShownLaunchers.values() + sortedHiddenLaunchers);
+    QStringList sortedLaunchers = leadingHiddenLaunchers;
+
+    for (const auto &[row, launcherUrlStr] : sortedShownLaunchers.asKeyValueRange()) {
+        sortedLaunchers << launcherUrlStr << hiddenLaunchersAfterRow.value(row);
+    }
+
+    setLauncherList(sortedLaunchers);

     // The accepted rows are outdated after the item order is changed
     invalidateFilter();
-- 
